function base64urlToUint8Array(base64url) {
	if (!base64url || typeof base64url !== 'string') {
		console.error('Invalid base64url input:', base64url);
		throw new Error('Invalid base64url input: ' + base64url);
	}
    
	// Add padding if needed
	const padding = '='.repeat((4 - base64url.length % 4) % 4);
	const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/') + padding;
    
	const binary = atob(base64);
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i++) {
		bytes[i] = binary.charCodeAt(i);
	}
	return bytes;
}

// Helper function to convert Uint8Array to base64url
function uint8ArrayToBase64url(uint8Array) {
	const base64 = btoa(String.fromCharCode(...uint8Array));
	return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}


function handleWebAuthnError(error, mFA) {
	// Show safe message to user
	mFA.set("ErrorType", error?.name || "UnknownError") 
	mFA.set("MessageType", "Error")
	throw new Error(error + " " + ((typeof navigator !== "undefined" && navigator.userAgent) ? navigator.userAgent : ""));

}

